#!/bin/bash\n\n# BUYI Documentation Conversion Script\n# Simpler version: Creates folder structure and logs instructions\n\nBASE_DIR=\"/Users/mac/Documents/BUYISPACE/docs\"\nPDF_OUTPUT_DIR=\"$BASE_DIR/PDF_Output\"\nBY_VOLUME_DIR=\"$PDF_OUTPUT_DIR/By_Volume\"\nBY_CATEGORY_DIR=\"$PDF_OUTPUT_DIR/By_Category\"\nLOG_FILE=\"$BASE_DIR/LOG.md\"\n\n# Parse arguments\nFORCE_REBUILD=false\nCLEAN_MODE=false\n\nif [[ \"$1\" == \"--force\" ]]; then\n    FORCE_REBUILD=true\nelif [[ \"$1\" == \"--clean\" ]]; then\n    CLEAN_MODE=true\nfi\n\n# Start logging\n{\n    echo \"# BUYI Documentation PDF Conversion Log\"\n    echo \"\"\n    echo \"**Generated:** $(date)\"\n    echo \"**Platform:** macOS $(sw_vers -productVersion)\"\n    echo \"**Options:** Force=$FORCE_REBUILD, Clean=$CLEAN_MODE\"\n    echo \"\"\n    echo \"Base directory: $BASE_DIR\"\n    echo \"\"\n    \n    # Clean mode\n    if [ \"$CLEAN_MODE\" = true ]; then\n        echo \"[CLEAN MODE] Deleting all existing PDFs...\"\n        rm -rf \"$PDF_OUTPUT_DIR\"\n        echo \"✓ All PDFs deleted\"\n        echo \"\"\n    fi\n    \n    # Create output directories\n    echo \"Creating folder structure...\"\n    mkdir -p \"$BY_VOLUME_DIR\"\n    mkdir -p \"$BY_CATEGORY_DIR\"\n    mkdir -p \"$BY_CATEGORY_DIR/Quick_Reference\"\n    mkdir -p \"$BY_CATEGORY_DIR/Executive\"\n    mkdir -p \"$BY_CATEGORY_DIR/Requirements\"\n    mkdir -p \"$BY_CATEGORY_DIR/Architecture\"\n    mkdir -p \"$BY_CATEGORY_DIR/Planning\"\n    mkdir -p \"$BY_CATEGORY_DIR/Operations\"\n    echo \"✓ Folder structure created\"\n    echo \"\"\n    \n    # Check for existing files\n    echo \"## Files Ready for Conversion\"\n    echo \"\"\n    \n    FILES_FOUND=0\n    \n    for md_file in \"$BASE_DIR\"/*.md; do\n        if [ -f \"$md_file\" ]; then\n            filename=$(basename \"$md_file\" .md)\n            # Skip LOG.md itself\n            if [[ \"$filename\" == \"LOG\" ]]; then\n                continue\n            fi\n            echo \"  ✓ Found: $filename.md\"\n            ((FILES_FOUND++))\n        fi\n    done\n    \n    echo \"\"\n    echo \"Total markdown files found: $FILES_FOUND\"\n    echo \"\"\n    \n    echo \"## Recommended Conversion Methods\"\n    echo \"\"\n    echo \"### Option 1: Google Docs (Easiest, No Installation)\"\n    echo \"For each markdown file:\"\n    echo \"1. Open Google Docs: https://docs.google.com\"\n    echo \"2. Create new document\"\n    echo \"3. Copy-paste markdown content\"\n    echo \"4. File → Download → PDF (.pdf)\"\n    echo \"5. Save to: $BY_VOLUME_DIR/\"\n    echo \"\"\n    \n    echo \"### Option 2: VS Code Extension (1-Click)\"\n    echo \"Prerequisites:\"\n    echo \"  - Have VS Code installed\"\n    echo \"  - Install 'Markdown PDF' extension (by yzane)\"\n    echo \"\"\n    echo \"Then for each file:\"\n    echo \"1. Open file in VS Code\"\n    echo \"2. Right-click → Select 'Markdown PDF: Export (pdf)'\"\n    echo \"3. Save to: $BY_VOLUME_DIR/\"\n    echo \"\"\n    \n    echo \"### Option 3: Install Pandoc (Advanced, Recommended for Batch)\"\n    echo \"Prerequisites:\"\n    echo \"  brew install pandoc\"\n    echo \"  brew install --cask basictex  (or install MacTeX from https://tug.org/mactex/)\"\n    echo \"\"\n    echo \"Then run: bash convert-to-pdf-pandoc.sh\"\n    echo \"\"\n    \n    echo \"### Option 4: Manual Print to PDF\"\n    echo \"For each markdown file:\"\n    echo \"1. Open file in any text editor (TextEdit, VS Code, etc)\"\n    echo \"2. File → Print\"\n    echo \"3. Bottom-left: Click 'PDF' dropdown\"\n    echo \"4. Select 'Save as PDF'\"\n    echo \"5. Save to: $BY_VOLUME_DIR/\"\n    echo \"\"\n    \n    echo \"## File Organization\"\n    echo \"\"\n    echo \"After conversion, organize PDFs as follows:\"\n    echo \"\"\n    echo \"### By_Volume/ (Sequential Reading)\"\n    echo \"  00-README.pdf\"\n    echo \"  01-vol-1-prd.pdf\"\n    echo \"  02-vol-2-srs.pdf\"\n    echo \"  03-vol-3-ddd-blueprint.pdf\"\n    echo \"  04-vol-4-system-architecture.pdf\"\n    echo \"  05-vol-5-event-catalog.pdf\"\n    echo \"  06-vol-6-build-roadmap.pdf\"\n    echo \"  07-vol-7-financial-implications.pdf\"\n    echo \"\"\n    echo \"### By_Category/ (Role-Based Access)\"\n    echo \"  Quick_Reference/\"\n    echo \"    - README.pdf\"\n    echo \"  Requirements/\"\n    echo \"    - 01-Product-Requirements.pdf (vol-1-prd.pdf)\"\n    echo \"    - 02-Software-Requirements.pdf (vol-2-srs.pdf)\"\n    echo \"  Architecture/\"\n    echo \"    - 01-DDD-Blueprint.pdf (vol-3)\"\n    echo \"    - 02-System-Architecture.pdf (vol-4)\"\n    echo \"    - 03-Event-Catalog.pdf (vol-5)\"\n    echo \"  Planning/\"\n    echo \"    - 01-Build-Roadmap.pdf (vol-6)\"\n    echo \"  Operations/\"\n    echo \"    - 01-Financial-Implications.pdf (vol-7)\"\n    echo \"\"\n    \n    echo \"## Output Locations\"\n    echo \"\"\n    echo \"**By Volume:** $BY_VOLUME_DIR\"\n    echo \"**By Category:** $BY_CATEGORY_DIR\"\n    echo \"\"\n    echo \"## Status\"\n    echo \"✓ Folder structure ready\"\n    echo \"✓ Instructions generated\"\n    echo \"\"\n    echo \"Next step: Choose a conversion method from above and convert files.\"\n    echo \"\"\n    echo \"Completed: $(date)\"\n    \n} > \"$LOG_FILE\" 2>&1\n\n# Display summary\ncat \"$LOG_FILE\"\n\necho \"\"\necho \"✓ Setup complete. Full log saved to LOG.md\"\necho \"\"\necho \"📁 Folders created:\"\necho \"   open \\\"$PDF_OUTPUT_DIR\\\"\"\necho \"\"\n